mapper.select:
SELECT

FROM member_notifications n
LEFT JOIN members actor
    ON actor.member_id = n.actor_member_id
WHERE n.recipient_member_id = #{recipientMemberId}

    AND n.notification_id < #{cursor.cursorNotificationId}

ORDER BY n.notification_id DESC
LIMIT #{cursor.size}

mapper.update:
UPDATE member_notifications
SET read_at = COALESCE(read_at, CURRENT_TIMESTAMP)
WHERE notification_id = #{notificationId}
    AND recipient_member_id = #{recipientMemberId}

mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM member_notifications
    WHERE notification_event_key = #{notificationEventKey}
)
